.sf-panel{margin-top:16px;padding-top:13px;border-top:1px solid var(--od-line,#e1e8f1)}.sf-panel h3{margin-bottom:7px}.sf-inline{display:grid;grid-template-columns:minmax(0,1fr) 70px auto;gap:6px;align-items:center}.sf-inline input,.sf-inline button{margin:0!important}.sf-weekdays{display:flex;justify-content:space-between;gap:1px;flex-wrap:wrap;margin:10px 0}.sf-weekdays label{font-size:10px!important;display:flex;align-items:center;gap:2px}.sf-groups{font-size:10px;color:var(--od-sub,#53647e)}.sf-group{display:flex;gap:6px;align-items:center;justify-content:space-between;padding:5px 0}.sf-group button{min-height:26px}
