/* Side Panel widths and zoom may reduce the sandbox viewport below 360px.
   Keep the tool's own 12px gutter; do not inherit a second host page inset. */
@media(max-width:360px){.sf{padding:var(--space-3,12px)}.sf-site{align-items:stretch;flex-direction:column}.sf-site-actions{width:100%;flex-wrap:wrap}.sf-site-actions button{flex:1;min-width:0}.sf-inline{grid-template-columns:minmax(0,1fr) 72px}.sf-inline button{grid-column:1/-1}.sf-actions button{flex:1}.sf-two{grid-template-columns:minmax(0,1fr)}}
@media(max-width:320px){.sf-heading{flex-wrap:wrap}.sf-state{max-width:100%;white-space:normal}}
/* This isolated sandbox has no access to the host's CSS: map the canonical
   OpenDesk semantic dark palette locally, without importing trusted styles. */
@media(prefers-color-scheme:dark){
.sf{--od-ink:var(--od-dark-ink,#e9eef7);--od-sub:var(--od-dark-sub,#b3c1d3);
  --od-line:var(--od-dark-line,#374457);--od-brand:var(--od-dark-brand,#3566ba);
  --od-paper:var(--od-dark-paper,#151c28);--od-bg:var(--od-dark-bg,#101722);
  --od-input-border:var(--od-dark-input-border,#52627a);
  --od-negative:var(--od-dark-negative,#ff9ea6)}
.sf-progress{background:var(--od-dark-muted,#222d3e)}
.sf-state,.sf-state[data-active=true],.sf-state[data-blocked=true],.sf-state[data-warning=true]{
  background:var(--od-dark-muted,#222d3e);color:var(--od-ink)}
.sf-state[data-blocked=true]{border:1px solid var(--od-negative)}
.sf-state[data-warning=true]{border:1px solid var(--od-input-border)}
}
@media(prefers-reduced-motion:reduce){.sf-progress i{transition:none}}
/* A single shared daily pool: prominent facts and compact editing. */
.sf-budget-total{display:flex;flex-wrap:wrap;align-items:baseline;gap:8px;margin:7px 0 11px}
.sf-budget-total strong{display:inline!important;font-size:23px!important;margin:0!important}
.sf-budget-total span{color:var(--od-sub,#53647e);font-size:11px}
.sf-stats{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.sf-stats>div{padding:10px;background:var(--od-bg,#f5f7fb);border-radius:9px}
.sf-stats span{font-size:11px;color:var(--od-sub,#53647e);display:block}
.sf-stats strong{display:block;font-size:21px!important;margin:4px 0 0!important;line-height:1.2!important}
.sf-budget-form{display:grid;grid-template-columns:minmax(0,1fr) 80px auto;gap:8px;align-items:center;margin-top:12px}
.sf-budget-form label{margin:0;font-size:11px!important}
.sf-budget-form input{margin:0!important;text-align:center}
.sf-budget-form button{min-width:72px}
@media(max-width:335px){.sf-budget-form{grid-template-columns:1fr 76px}.sf-budget-form label{grid-column:1/-1}}

.sf-managed-details{margin-top:9px}
.sf-managed-details>summary{cursor:pointer;color:var(--od-brand,#365eda);font-size:12px;font-weight:650;padding:7px 0}
.sf-managed-details>.sf-list{margin-top:7px}

